library(ggplot2)
out <- 'output/MSI2_analysis_progression_final/assets'
p <- read.delim('output/external_rbp_splice_comparison/splice_bin_profiles.tsv')
p <- subset(p, abs(bin_center)<250)
p$RBP <- factor(p$RBP,levels=c('MSI2','QKI','PUM2','ELAVL1'))
p$boundary <- factor(p$boundary,levels=c('donor','acceptor'))
g <- ggplot(p,aes(bin_center,observed_expected))+geom_ribbon(aes(ymin=null_low_OE,ymax=null_high_OE),fill='grey85')+geom_hline(yintercept=1,linetype=2,color='grey50')+geom_vline(xintercept=0,color='grey50')+geom_line(color='#176B78',linewidth=.7)+facet_grid(boundary~RBP)+labs(x='Distance from splice boundary (nt)',y='Observed / expected peak fraction')+theme_bw(base_size=16)+theme(panel.grid.minor=element_blank(),strip.background=element_rect(fill='grey95'))
ggsave(file.path(out,'external_landscape.png'),g,width=14,height=5.3,dpi=220)
a <- read.delim('output/round2_comparisons/tables/metaprofiles_all_samples.tsv')
b <- read.delim('output/round2_comparisons/tables/metaprofile_group_means.tsv')
a <- subset(a,variant=='all__genome_full' & kind %in% c('splice_donor','splice_acceptor'))
b <- subset(b,variant=='all__genome_full' & kind %in% c('splice_donor','splice_acceptor'))
print(unique(b$kind));stopifnot(nrow(b)>0)
g <- ggplot(b,aes(x,depth,color=group,linetype=assay))+geom_line(data=a,aes(y=mean_depth_per_feature_per_million_reads,group=sample_id),alpha=.3,linewidth=.4)+geom_line(linewidth=.9)+geom_vline(xintercept=0,color='grey40')+facet_wrap(~kind,nrow=1)+scale_color_manual(values=c('324 CLIP'='#147A80','324 SMI'='#80B7B8','328 CLIP'='#C66734','328 SMI'='#DEA886'))+labs(x='Distance from boundary (nt)',y='Mean aligned-base depth / million reads',color=NULL,linetype=NULL)+theme_bw(base_size=16)+theme(legend.position='bottom',panel.grid.minor=element_blank())
ggsave(file.path(out,'expanded_full_genome.png'),g,width=12,height=6,dpi=220)
